local ServiceCollection = require(script.Parent.ServiceCollection)
local ServiceDescriptor = require(script.Parent.ServiceDescriptor)

return function()
	describe("ServiceCollection", function()
		local collection

		beforeEach(function()
			collection = ServiceCollection.new()
		end)

		it("should create a new empty collection", function()
			expect(#collection._descriptors).to.equal(0)
			expect(collection._isReadOnly).to.equal(false)
		end)

		it("should add a service descriptor", function()
			local descriptor = ServiceDescriptor.new("TestService", function() end, "Singleton")
			collection:Add(descriptor)
			expect(#collection._descriptors).to.equal(1)
			expect(collection:Contains(descriptor)).to.equal(true)
		end)

		it("should clear all descriptors", function()
			local descriptor1 = ServiceDescriptor.new("TestService1", function() end, "Singleton")
			local descriptor2 = ServiceDescriptor.new("TestService2", function() end, "Transient")
			collection:Add(descriptor1)
			collection:Add(descriptor2)
			collection:Clear()
			expect(#collection._descriptors).to.equal(0)
		end)

		it("should remove a specific descriptor", function()
			local descriptor1 = ServiceDescriptor.new("TestService1", function() end, "Singleton")
			local descriptor2 = ServiceDescriptor.new("TestService2", function() end, "Transient")
			collection:Add(descriptor1)
			collection:Add(descriptor2)
			local removed = collection:Remove(descriptor1)
			expect(removed).to.equal(true)
			expect(#collection._descriptors).to.equal(1)
			expect(collection:Contains(descriptor1)).to.equal(false)
			expect(collection:Contains(descriptor2)).to.equal(true)
		end)

		it("should insert a descriptor at a specific index", function()
			local descriptor1 = ServiceDescriptor.new("TestService1", function() end, "Singleton")
			local descriptor2 = ServiceDescriptor.new("TestService2", function() end, "Transient")
			local descriptor3 = ServiceDescriptor.new("TestService3", function() end, "Scoped")
			collection:Add(descriptor1)
			collection:Add(descriptor2)
			collection:Insert(2, descriptor3)
			expect(#collection._descriptors).to.equal(3)
			expect(collection:IndexOf(descriptor3)).to.equal(2)
		end)

		it("should remove a descriptor at a specific index", function()
			local descriptor1 = ServiceDescriptor.new("TestService1", function() end, "Singleton")
			local descriptor2 = ServiceDescriptor.new("TestService2", function() end, "Transient")
			collection:Add(descriptor1)
			collection:Add(descriptor2)
			collection:RemoveAt(1)
			expect(#collection._descriptors).to.equal(1)
			expect(collection:Contains(descriptor1)).to.equal(false)
			expect(collection:Contains(descriptor2)).to.equal(true)
		end)

		it("should make the collection read-only", function()
			collection:MakeReadOnly()
			expect(collection._isReadOnly).to.equal(true)
			expect(function()
				collection:Add(ServiceDescriptor.new("TestService", function() end, "Singleton"))
			end).to.throw("Service Collection Read Only")
		end)
	end)
end
